processor-info.script:

String cmd = input.getText("cmd");


if( "INSERT_USER_LECTURE".equals(cmd) )
{
	executeSQL(cmd, connection, input, output);
	executeSQL("GET_USER_LECTURE_KEY", connection, input, output);
}else if( "SET_SELECT_CLASS".equals(cmd) )
{
	DataSet all = new DataSet();
	all.put( "status" , "9" );
	all.put( "user_lecture_seq_no" , input.getText("user_lecture_seq_no") );

	executeSQL("UPDATE_USER_CLASS_STATUS", connection, all, output);

	DataSet ins = new DataSet();
	for( int idx =0 ; idx < input.getCount("class_nos"); idx++)
	{
		ins = new DataSet();
		ins.put( "status" , "0" );
		ins.put( "class_no" , input.getText("class_nos", idx) );
		ins.put( "user_lecture_seq_no" , input.getText("user_lecture_seq_no") );
		executeSQL("UPDATE_USER_SELECT_CLASS", connection, ins, output);
	}
}else{
	executeSQL(cmd, connection, input, output);
}
